INSERT INTO public.restaurants (name, slug, category, cuisine_type, description, short_description, image_url, address, phone, email, website, price_range, opening_hours, rating, review_count, services, signature_dishes, is_featured, is_active, latitude, longitude)
VALUES
('Meson de Bari', 'meson-de-bari', 'local', 'Dominicana', 'El Mesón de Bari es un templo de la gastronomía dominicana tradicional. Desde 1956, este restaurante familiar ha servido los platos más auténticos de la cocina criolla.', 'Cocina criolla dominicana auténtica desde 1956.', 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?w=800', 'Av. Hostos 302, Zona Colonial, Santo Domingo', '+1 809-687-4091', NULL, NULL, '$$', 'Lun-Dom 7:00 AM - 10:00 PM', 4.5, 1540, ARRAY['Comida para llevar', 'Delivery', 'WiFi', 'Grupos grandes'], ARRAY['La Bandera Dominicana', 'Mofongo Relleno', 'Chivo Guisado', 'Sancocho de 7 Carnes'], true, true, 18.4720, -69.8870),
('La Yola', 'la-yola', 'seafood', 'Mariscos Mediterránea', 'Situado sobre el mar en la Marina de Cap Cana, La Yola ofrece mariscos frescos y cocina mediterránea en un ambiente mágico.', 'Mariscos frescos sobre el mar Caribe en Cap Cana.', 'https://images.unsplash.com/photo-1590846406792-0adc7f938f1d?w=800', 'Marina Cap Cana, Punta Cana', '+1 809-227-2262', 'reservas@layola.do', 'https://layola.do', '$$$$', 'Lun-Dom 12:00 PM - 11:00 PM', 4.8, 673, ARRAY['Vista al mar', 'Reservaciones obligatorias', 'Carta de vinos premium', 'Valet parking'], ARRAY['Langosta a la Parrilla', 'Ceviche de Camarón', 'Paella Marinera', 'Atún Sellado'], true, true, 18.4620, -68.3940),
('Peperoni', 'peperoni-ristorante', 'casual', 'Italiana', 'Peperoni es el restaurante italiano más querido de Santo Domingo con pizzas artesanales de horno de leña.', 'Auténtica cocina italiana con pizzas artesanales en Santo Domingo.', 'https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?w=800', 'Av. Roberto Pastoriza 226, Naco, Santo Domingo', '+1 809-562-5057', NULL, 'https://peperoni.com.do', '$$', 'Lun-Dom 12:00 PM - 12:00 AM', 4.4, 2100, ARRAY['Delivery', 'Terraza', 'WiFi', 'Para niños'], ARRAY['Pizza Peperoni Especial', 'Pasta Carbonara', 'Lasagna de la Casa'], false, true, 18.4650, -69.9200),
('Boca Marina', 'boca-marina', 'seafood', 'Mariscos Dominicana', 'Icónico restaurante de mariscos frente al mar en Boca Chica con décadas de tradición.', 'Mariscos frescos frente al mar en Boca Chica.', 'https://images.unsplash.com/photo-1559339352-11d035aa65de?w=800', 'Playa Boca Chica, San Pedro de Macorís', '+1 809-523-4303', NULL, NULL, '$$', 'Lun-Dom 10:00 AM - 10:00 PM', 4.3, 980, ARRAY['Frente al mar', 'Grupos grandes', 'Música en vivo'], ARRAY['Langosta Boca Marina', 'Pescado Frito al Coco', 'Camarones al Ajillo'], false, true, 18.4500, -69.6100)
