('Tortuga Bay', 'tortuga-bay', 'boutique', 'Hotel boutique diseñado por Oscar de la Renta con playa privada y servicio de mayordomo en Punta Cana.', 'Hotel boutique diseñado por Oscar de la Renta en Punta Cana.', 'https://images.unsplash.com/photo-1582719508461-905c673771fd?w=800', 'Puntacana Resort & Club, Punta Cana', '+1 809-959-2262', 'reservas@tortugabay.com', 'https://tortugabay.puntacana.com', '$$$$', 5, 4.9, 456, ARRAY['Playa privada', 'Spa', 'Golf', 'Butler service', 'Piscina infinita', 'WiFi', 'Transfer aeropuerto'], true, true, 18.5100, -68.3680),
('Casa Colonial Beach & Spa', 'casa-colonial', 'boutique', 'Resort boutique colonial de cinco estrellas frente a la playa en Puerto Plata.', 'Resort boutique colonial en Puerto Plata.', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?w=800', 'Playa Dorada, Puerto Plata', '+1 809-320-3232', 'info@casacolonial.com', 'https://casacolonial.com', '$$$', 5, 4.7, 678, ARRAY['Spa', 'Playa privada', 'Restaurante gourmet', 'Piscina', 'WiFi', 'Gimnasio'], true, true, 19.7800, -70.6900),
('Sublime Samana', 'sublime-samana', 'boutique', 'Resort eco-chic con villas de piscina privada en la península de Samaná.', 'Resort eco-chic en Samaná.', 'https://images.unsplash.com/photo-1520250497591-112f2f40a3f4?w=800', 'Carretera Las Terrenas-El Limón, Samaná', '+1 809-240-5555', 'reservations@sublimesamana.com', 'https://sublimesamana.com', '$$$', 5, 4.8, 342, ARRAY['Piscinas privadas', 'Spa orgánico', 'Yoga', 'Restaurante farm-to-table', 'WiFi', 'Bicicletas'], true, true, 19.3100, -69.5400),
('Zoëtry Agua Punta Cana', 'zoetry-agua', 'all-inclusive', 'Resort all-inclusive de lujo boutique con enfoque en bienestar en Punta Cana.', 'All-inclusive boutique de bienestar en Punta Cana.', 'https://images.unsplash.com/photo-1571003123894-1f0594d2b5d9?w=800', 'Playa Uvero Alto, Punta Cana', '+1 809-468-0000', 'info@zoetryagua.com', 'https://zoetryresorts.com', '$$$$', 5, 4.6, 890, ARRAY['Todo incluido', 'Spa', 'Yoga', 'Snorkel', 'Kayak', 'WiFi', 'Restaurantes gourmet'], false, true, 18.7200, -68.5100)
INSERT INTO public.experiences (name, slug, category, experience_type, description, short_description, image_url, duration, difficulty, price_range, best_season, included, requirements, highlights, rating, review_count, is_featured, is_active)
VALUES
('Canyoning en Damajagua', 'canyoning-damajagua', 'aventura', 'outdoor', 'Descubre las 27 cascadas de Damajagua en una aventura de canyoning única.', 'Salta y deslízate por las 27 cascadas de Damajagua.', 'https://images.unsplash.com/photo-1504280390367-361c6d9f38f4?w=800', '4-5 horas', 'moderado', '$$', 'Todo el año', ARRAY['Guía certificado', 'Equipo de seguridad', 'Transporte'], ARRAY['Saber nadar', 'Buena condición física'], ARRAY['27 cascadas naturales', 'Saltos de hasta 8 metros', 'Toboganes de roca', 'Selva tropical'], 4.8, 1250, true, true),
('Tour Zona Colonial', 'tour-zona-colonial', 'cultural', 'walking-tour', 'Camina por las calles empedradas de la primera ciudad del Nuevo Mundo.', 'Recorrido histórico por la Zona Colonial de Santo Domingo.', 'https://images.unsplash.com/photo-1558642452-9d2a7deb7f62?w=800', '3 horas', 'fácil', '$', 'Todo el año', ARRAY['Guía historiador', 'Entrada a monumentos', 'Degustación de chocolate'], ARRAY['Calzado cómodo', 'Protección solar'], ARRAY['Catedral Primada de América', 'Alcázar de Colón', 'Fortaleza Ozama'], 4.6, 890, true, true),
('Kayak Bioluminiscente Laguna Gri-Gri', 'kayak-bioluminiscente', 'naturaleza', 'water', 'Navega en kayak bajo las estrellas por la mágica Laguna Gri-Gri donde el agua se ilumina.', 'Kayak nocturno en aguas bioluminiscentes.', 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?w=800', '2 horas', 'fácil', '$$', 'Abril - Noviembre', ARRAY['Kayak doble', 'Guía nocturno', 'Chaleco salvavidas'], ARRAY['Saber nadar'], ARRAY['Bioluminiscencia natural', 'Cielo estrellado', 'Manglares'], 4.9, 340, true, true)
